import hashlib
import itertools
import time

def crack_password(hashed_password, wordlist_path=None, max_length=8, hash_type="sha256"):
    """
    Attempts to crack a password given its hash.

    Args:
        hashed_password (str): The hashed password to crack.
        wordlist_path (str, optional): Path to a wordlist file. If None, uses a simple built-in wordlist.
        max_length (int, optional): Maximum length of passwords to generate (if no wordlist).
        hash_type (str, optional): The hashing algorithm used (e.g., "md5", "sha1", "sha256").

    Returns:
        str: The cracked password if found, or None if not found.
    """

    def hash_string(string_to_hash, algorithm="sha256"):
        """Hashes a string using the specified algorithm."""
        string_bytes = string_to_hash.encode('utf-8')  # Encode to bytes
        if algorithm == "md5":
            return hashlib.md5(string_bytes).hexdigest()
        elif algorithm == "sha1":
            return hashlib.sha1(string_bytes).hexdigest()
        elif algorithm == "sha256":
            return hashlib.sha256(string_bytes).hexdigest()
        elif algorithm == "sha512":
            return hashlib.sha512(string_bytes).hexdigest()
        else:
            raise ValueError(f"Unsupported hashing algorithm: {algorithm}")

    def generate_passwords(length):
        """Generates all possible passwords of a given length using lowercase letters and digits."""
        chars = "abcdefghijklmnopqrstuvwxyz0123456789"
        for combination in itertools.product(chars, repeat=length):
            yield "".join(combination)

    start_time = time.time()

    # 1. Try using a wordlist (if provided)
    if wordlist_path:
        try:
            with open(wordlist_path, "r", encoding="utf-8") as f:
                for word in f:
                    word = word.strip()  # Remove leading/trailing whitespace
                    hashed_word = hash_string(word, hash_type)
                    if hashed_word == hashed_password:
                        print(f"Password cracked using wordlist: {word}")
                        print(f"Time taken: {time.time() - start_time:.4f} seconds")
                        return word
        except FileNotFoundError:
            print(f"Wordlist file not found: {wordlist_path}")
        except Exception as e:
            print(f"Error reading wordlist: {e}")


    # 2. Try brute-force (if no wordlist or wordlist failed)
    print("Trying brute-force...")
    for length in range(1, max_length + 1):
        print(f"Trying passwords of length {length}...")
        for password in generate_passwords(length):
            hashed_password_candidate = hash_string(password, hash_type)
            if hashed_password_candidate == hashed_password:
                print(f"Password cracked using brute-force: {password}")
                print(f"Time taken: {time.time() - start_time:.4f} seconds")
                return password

    print("Password not found.")
    print(f"Time taken: {time.time() - start_time:.4f} seconds")
    return None


